[{"order":1,"type":"heading","text":"Cypress Component Testing for React, Vue, and Angular"},{"order":2,"type":"paragraph","text":"Cypress Component Testing allows you to mount and test individual components in isolation without spinning up a full server or relying on end-to-end infrastructure. This tutorial covers setup and testing patterns for React, Vue, and Angular."},{"order":3,"type":"heading","text":"Prerequisites and Installation"},{"order":4,"type":"paragraph","text":"To get started with Cypress Component Testing, install Cypress in your existing frontend project using your package manager."},{"order":5,"type":"code","text":"npm install cypress --save-dev"},{"order":6,"type":"paragraph","text":"Next, open the Cypress Launchpad to automatically configure component testing for your framework of choice."},{"order":7,"type":"code","text":"npx cypress open"},{"order":8,"type":"bullet_point","text":"Select 'Component Testing' in the UI."},{"order":9,"type":"bullet_point","text":"Cypress will automatically detect your framework (React, Vue, or Angular) and build tool (Vite, Webpack, etc.)."},{"order":10,"type":"bullet_point","text":"Approve the generated configuration files."},{"order":11,"type":"heading","text":"Testing React Components"},{"order":12,"type":"paragraph","text":"For React, Cypress uses the mount function to render JSX elements inside a real browser context. Here is an example of testing a simple button component."},{"order":13,"type":"code","text":"import React from 'react';
import { Button } from './Button';

describe('<Button />', () => {
  it('renders and fires click event', () => {
    const onClickSpy = cy.spy().as('onClickSpy');
    cy.mount(<Button label="Click Me" onClick={onClickSpy} />);

    cy.get('button').should('have.text', 'Click Me');
    cy.get('button').click();
    cy.get('@onClickSpy').should.have.been.calledOnce;
  });
});"},{"order":14,"type":"heading","text":"Testing Vue Components"},{"order":15,"type":"paragraph","text":"For Vue (supporting Vue 2 and Vue 3), Cypress mounts single-file components using the mount function from 'cypress/vue'."},{"order":16,"type":"code","text":"import { mount } from 'cypress/vue';
import UserCard from './UserCard.vue';

describe('UserCard.vue', () => {
  it('displays user props correctly', () => {
    mount(UserCard, {
      props: {
        name: 'Jane Doe',
        role: 'Administrator'
      }
    });

    cy.get('.username').should('have.text', 'Jane Doe');
    cy.get('.role').should('have.text', 'Administrator');
  });
});"},{"order":17,"type":"heading","text":"Testing Angular Components"},{"order":18,"type":"paragraph","text":"Angular component testing uses TestBed functionality under the hood via 'cypress/angular'. You can mount standalone components or traditional NgModule-based components."},{"order":19,"type":"code","text":"import { mount } from 'cypress/angular';
import { ProfileComponent } from './profile.component';

describe('ProfileComponent', () => {
  it('renders profile title', () => {
    mount(ProfileComponent, {
      componentProperties: {
        title: 'User Dashboard'
      }
    });

    cy.get('h1').should('have.text', 'User Dashboard');
  });
});"},{"order":20,"type":"heading","text":"Conclusion"},{"order":21,"type":"paragraph","text":"Cypress Component Testing brings the power of real-browser execution, network stubbing, and spies to individual UI elements. Regardless of whether your stack is React, Vue, or Angular, the testing methodology remains consistent, robust, and fast."}]
